#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 1c: file storage and the usage ledger
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now an uploaded video sat on the API service's own disk until it
# was processed. Render wipes that disk on every deploy, so a deploy in
# the middle of processing lost the file. And nothing recorded how much
# transcription, AI or storage each account used.
#
# After this part:
#   * uploads go through one storage adapter with two drivers: local disk
#     (the default, behaves as before) and any S3 compatible store such
#     as Cloudflare R2 (durable). The driver is chosen by settings only.
#   * with S3 storage the original is kept, a deploy mid processing loses
#     nothing, and a failed step can be retried without a new upload
#   * the server proves storage works at startup and reports it at
#     /api/health
#   * every transcribed second, AI token and stored byte is written to a
#     usage ledger per owner, video and feature. Quantities only, no money.
#   * GET /api/usage/me returns the signed in wallet's totals
#
#   BACKEND   4 new files, 12 changed. One migration (media_assets and
#             usage_ledger tables), applied once when the service starts.
#   FRONTEND  no changes.
#
# Adds three packages to the backend: @aws-sdk/client-s3,
# @aws-sdk/lib-storage, @aws-sdk/s3-request-presigner. The script writes
# the tested package.json and lockfile, then runs npm install in backend/.
#
#   ./vm_storage.sh            apply (needs Part 1b applied)
#   ./vm_storage.sh --force    apply even if local files differ
#   ./vm_storage.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_storage"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_storage_backups"

ADD=(
  "backend/src/lib/storage.ts"
  "backend/src/lib/usage.ts"
  "backend/src/lib/assets.ts"
  "backend/src/routes/usage.ts"
)
MOD=(
  "backend/package.json"
  "backend/package-lock.json"
  "backend/.env.example"
  "backend/src/index.ts"
  "backend/src/worker.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/routes/videos.ts"
  "backend/src/routes/chat.ts"
  "backend/src/routes/learn.ts"
  "backend/src/services/aiPipeline.ts"
  "backend/src/services/learningService.ts"
  "backend/src/services/pipeline.ts"
)
PRE_MOD=(
  "947ab6fff73e3982f26087b28043cc5faad9c6174883ccfd6a483021d4df6d6d"
