grep -q "$MARKER" "$TMPD/a0"                 || die "storage.ts payload missing marker. Aborting."
grep -q 'WHEN_REQUIRED' "$TMPD/a0"           || die "storage.ts payload lost the checksum setting. Aborting."
grep -q 'ON CONFLICT(idempotency_key)' "$TMPD/a1" || die "usage.ts payload lost the duplicate guard. Aborting."
grep -q 'requireAuth' "$TMPD/m6"             || die "videos.ts payload lost the sign in guard. Aborting."
grep -q 'limitDelete' "$TMPD/m6"             || die "videos.ts payload lost the delete limit. Aborting."
grep -q 'enqueueJob' "$TMPD/m6"              || die "videos.ts payload does not queue a job. Aborting."
grep -q 'saveOriginal' "$TMPD/m6"            || die "videos.ts payload does not use storage. Aborting."
grep -q '001_signin' "$TMPD/m5"              || die "migrations.ts payload lost the sign in migration. Aborting."
grep -q '002_jobs' "$TMPD/m5"                || die "migrations.ts payload lost the jobs migration. Aborting."
grep -q '003_storage_usage' "$TMPD/m5"       || die "migrations.ts payload missing the storage migration. Aborting."
grep -q '"@aws-sdk/client-s3"' "$TMPD/m0"   || die "package.json payload missing the storage packages. Aborting."
grep -q '"node_modules/@aws-sdk/client-s3"' "$TMPD/m1" || die "lockfile payload missing the storage packages. Aborting."
grep -q '"@shelby-protocol/sdk"' "$TMPD/m0" || die "package.json payload lost the Shelby SDK. Aborting."
say "16 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied file storage and the usage ledger (rebuild Part 1c)."

# ---- packages: the source is in place either way, so a failed install
# ---- is reported, not rolled back.
say "backend: installing the three storage packages (npm install) ..."
if (cd backend && npm install --no-audit --no-fund >/dev/null 2>&1); then
  say "backend packages installed."
else
  say "WARNING: npm install failed (no network?). The files are applied."
  say "         Run this yourself before the checks below: cd backend && npm install"
fi

say "Verify before pushing:"
say "  cd backend && npx tsc --noEmit"
say "Undo: ./vm_storage.sh --revert"
